"""큰 재화, 전투 효과(머리 위 능력치 칩, 11-23), 스킬 정보, 장착 머리 초상화 회귀 검사."""

def run(ctx):
    for name, kw in [('PC', {}), ('mobile', {'viewport': (800,360), 'touch': True}), ('mobile_small', {'viewport': (640,360), 'touch': True})]:
        g=ctx.game(**kw)
        g.enter_v2()
        g.js("gameState.darkMatter=123456789;progress.shards=12345;progress.cores=987654;progress.stones=1234567;gameState.notify();window.madOverlordGameV2.switchScreen('lab');")
        st=g.js("""const chips=[...document.querySelectorAll('#screen-lab-v2 [data-currency] .v2-chip:not([hidden])')];return {text:chips.map(e=>e.innerText).join(' '), fits:chips.every(e=>e.scrollWidth<=e.clientWidth+1),right:document.querySelector('#screen-lab-v2 .v2-topbar__right').getBoundingClientRect().left,brand:document.querySelector('#screen-lab-v2 .v2-brand').getBoundingClientRect().right};""")
        ctx.check('123M' in st['text'] and '12.3K' in st['text'] and st['fits'] and st['right']>=st['brand'],name+' large currency fits',str(st))
        g.shot('readability_currency_'+name,'#screen-lab-v2')
        g.equip('mech')
        g.js("gameState.equippedParts.head='head_mech_a';")
        g.battle(wait_ms=2900)
        st=g.js("return {src:document.querySelector('#hud-portrait-v2').getAttribute('src'),cut:b.hud.portraitSrc};")
        ctx.check(st['src'].endswith('/head_a.png') and st['cut']==st['src'],name+' equipped set head used in HUD and cut-in',str(st))
        g.js("b.addBuff('overdrive',6);b.applyPlayerSlow(4);b.applyPlayerVuln(4,.3);b.addKitBuff('readability',5,{dmg:.2});b.hud.update();gameTime.paused=true;")
        text=g.js("return [...document.querySelectorAll('.v2-buff-mark')].map(n=>n.textContent.replace(/\\s+/g,'')).join('|');")
        expect=['공속+50%','이속−50%','방어−30%','공격+20%'] if name=='PC' else ['이속−50%','방어−30%','공격+20%']   # 휴대폰은 5개 + '+N'
        ctx.check(all(x in text for x in expect),name+' head chips: one stat per chip (two-letter label + value)',text)
        ctx.check(g.js("const n=[...document.querySelectorAll('.v2-buff-mark')].sort((a,c)=>a.style.order-c.style.order);return n.length>1 && n.every((e,i)=>!i || e.getBoundingClientRect().bottom<=n[i-1].getBoundingClientRect().top+1) && document.querySelector('#hud-pstatus-v2').hidden;"),name+' chips stack upward from the head, profile summary gone')
        g.shot('readability_battle_'+name,'#screen-battle-v2')
        ctx.check(g.js("return [...document.querySelectorAll('#skill-dock-v2 .v2-skill-name')].every(e=>getComputedStyle(e).display!=='none' && e.textContent);"),name+' skill names visible')
        g.js("gameTime.paused=false; b.hud.showSkillHelp();")
        ctx.check(g.js("return gameTime.paused && document.querySelector('dialog.v2-skill-guide').open && document.querySelector('dialog.v2-skill-guide').innerText.includes(b.skills.arm.desc);"),name+' skill guide pauses and explains')
        ctx.check(g.js("const d=document.querySelector('.v2-skill-guide'),r=d.getBoundingClientRect();return r.left>0 && r.top>=0 && r.right<innerWidth && r.bottom<=innerHeight && d.scrollTop===0;"),name+' guide centered inside screen')
        g.shot('readability_guide_'+name)
        g.page.keyboard.press('Escape')
        g.wait(100)
        ctx.check(g.js("return !gameTime.paused && !document.querySelector('.v2-skill-guide');"),name+' close guide restores play state')
        g.js("gameTime.paused=true;b.hud.showSkillHelp();b.hud.skillHelp.close();")
        g.wait(100)
        ctx.check(g.js("return gameTime.paused;"),name+' guide preserves already paused state')
        g.js("b.buffs={};b.kitBuffs={};b.pSlowT=0;b.pVulnT=0;b.hud.update();")
        ctx.check(g.js("return document.querySelector('.v2-buff-marks').hidden;"),name+' expired effects disappear')
        g.js("b.director.ultCutIn(b.skills.head,b.hud.portraitSrc,b.hud.portraitFilter);")
        ctx.check(g.js("return document.querySelector('.v2-ultcut__face').getAttribute('src').endsWith('/head_a.png');"),name+' ultimate shows equipped head')
        g.js("const parts={head:gameState.getPartById('head','head_diver_up'),body:gameState.getPartById('body','body_diver'),arm:gameState.getPartById('arm','arm_diver'),leg:gameState.getPartById('leg','leg_diver')};m.renderVisuals(parts,'diver');await m.rigBattle.ready;b.hud.setPortrait(parts);await document.querySelector('#hud-portrait-v2').decode();")
        ctx.check(g.js("return document.querySelector('#hud-portrait-v2').src.endsWith('/diver/head_up.png') && document.querySelector('#hud-portrait-v2').naturalWidth>0;"),name+' upgraded head asset selected and loaded')
